", "t": [["write_file", "{"content":"#!/usr/bin/env python3\n\"\"\"Count word frequencies in a UTF-8 text file.\n\nUsage: python wordfreq.py FILE [-n N] [--min-len K]\n\"\"\"\n\nimport argparse\nimport sys\nfrom collections import Counter\n\n\ndef positive_int(value):\n    \"\"\"argparse type: must parse as an integer strictly greater than zero.\"\"\"\n    try:\n        number = int(value)\n    except ValueError:\n        raise argparse.ArgumentTypeError(f\"invalid integer: {value!r}\")\n    if number <= 0:\n        raise argparse.ArgumentTypeError(f\"must be a positive integer, got {value!r}\")\n    return number\n\n\ndef tokenize(text):\n    \"\"\"Yield lower-cased words: maximal runs of letters (any Unicode letter)\n    and ASCII apostrophes, with outer apostrophes stripped. Empty results are\n    skipped; digits and underscores are not part of words.\"\"\"\n    word = []\n    for ch in text:\n        if ch.isalpha() or ch == \"'\":\n            word.append(ch)\n        else:\n            if word:\n                token = \"\".join(word).lower().strip(\"'\")\n                if token:\n                    yield token\n                word = []\n    if word:\n        token = \"\".join(word).lower().strip(\"'\")\n        if token:\n            yield token\n\n\ndef main(argv=None):\n    parser = argparse.ArgumentParser(\n        prog=\"wordfreq.py\",\n        description=\"Print the N most frequent words in FILE (word count, most frequent first; ties alphabetical).\",\n    )\n    parser.add_argument(\"file\", help=\"input file, read as UTF-8\")\n    parser.add_argument(\"-n\", type=positive_int, default=10, metavar=\"N\",\n                        help=\"number of words to print (default: 10)\")\n    parser.add_argument(\"--min-len\", type=positive_int, default=1, metavar=\"K\",\n                        help=\"ignore words shorter than K characters (default: 1)\")\n    args = parser.parse_args(argv)\n\n    try:\n        with open(args.file, encoding=\"utf-8\") as handle:\n            text = handle.read()\n    except (OSError, UnicodeDecodeError):\n        print(f\"error: cannot read {args.file}\", file=sys.stderr)\n        return 1\n\n    counts = Counter()\n    for token in tokenize(text):\n        if len(token) >= args.min_len:\n            counts[token] += 1\n\n    ranked = sorted(counts.items(), key=lambda item: (-item[1], item[0]))[: args.n]\n\n    reconfigure = getattr(sys.stdout, \"reconfigure\", None)\n    if reconfigure is not None:\n        sys.stdout.reconfigure(encoding=\"utf-8\")\n    for word, count in ranked:\n        print(f\"{word} {count}\")\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n","path":"D:\\Projects\\local_ai\\strata-lab\\runs\\work\\hermes\\wordfreq-1794053258\\wordfreq.py"}"]]}

